var c=class{static encrypt(t,r="ezreader-secret-key"){try{let e=this.xorEncrypt(t,r);return btoa(e)}catch{return""}}static decrypt(t,r="ezreader-secret-key"){try{let e=atob(t);return this.xorEncrypt(e,r)}catch{return""}}static xorEncrypt(t,r){let e="";for(let n=0;n<t.length;n++){let s=t.charCodeAt(n)^r.charCodeAt(n%r.length);e+=String.fromCharCode(s)}return e}static getDecryptedEnv(t){let r=window.__ENV__?.[t];return r?this.decrypt(r):""}};export{c as a};
